  const byId = new Map(ELEMENTS.map(item => [item.id, item]));

  function find(key) {
    if (typeof key === 'number') return ELEMENTS.find(item => item.number === key) || null;
    if (typeof key !== 'string') return null;
    const normalized = key.trim().toLowerCase();
    return byId.get(normalized) ||
      ELEMENTS.find(item =>
        item.name.toLowerCase() === normalized ||
        String(item.number) === normalized ||
        item.name.toLowerCase().includes(normalized)
      ) || null;
  }

  function resolve(key, options) {
    const item = find(key);
    if (!item) return null;
    const mode = options && options.mode ? options.mode : 'css';
    if (mode === 'xpath') return item.xpath[0] || null;
    if (mode === 'all') return { ...item };
    return item.css[0] || null;
  }

  function selector(key, mode) {
    return resolve(key, { mode: mode || 'css' });
  }

  function get(key, context) {
    const item = find(key);
    if (!item) return null;
    const rootNode = context || document;
    const css = item.css[0];
    if (css) {
      try { return rootNode.querySelector(css); } catch (_) {}
    }
    const xp = item.xpath[0];
    if (xp && document.evaluate) {
      try {
        return document.evaluate(xp, rootNode, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
      } catch (_) {}
    }
    return null;
  }

  function getAll(key, context) {
    const item = find(key);
    if (!item) return [];
    const rootNode = context || document;
    const css = item.css[0];
    if (css) {
      try { return Array.from(rootNode.querySelectorAll(css)); } catch (_) {}
    }
    const xp = item.xpath[0];
    if (xp && document.evaluate) {
      try {
        const result = document.evaluate(xp, rootNode, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
        return Array.from({length: result.snapshotLength}, (_, i) => result.snapshotItem(i));
      } catch (_) {}
    }
    return [];
  }

  function waitFor(key, options) {
    const opts = Object.assign({ timeout: 10000, interval: 100, context: document }, options || {});
    return new Promise((resolvePromise, reject) => {
      const started = Date.now();
      const timer = setInterval(() => {
        const element = get(key, opts.context);
        if (element) {
          clearInterval(timer);
          resolvePromise(element);
        } else if (Date.now() - started >= opts.timeout) {
          clearInterval(timer);
          reject(new Error('Element not found: ' + key));
        }
      }, opts.interval);
    });
  }

